package org.flexstore.domain.twofactor.model

private const val DIGITS = 6
private val WELL_FORMED_CODE = Regex("[0-9]{$DIGITS}")

// The 6-digit code typed from an authenticator app, or computed by the server to check it
data class TwoFactorCode(val value: String) {

    fun isWellFormed() = WELL_FORMED_CODE.matches(value)

    companion object {
        // The code generated by the server from a counter: always 6 digits, padded with leading zeros
        fun of(counter: Int): TwoFactorCode = TwoFactorCode(counter.toString().padStart(DIGITS, '0'))
    }
}
